import{_ as r,C as n,o,c as d,a2 as a,b as s,w as i,a as c,E as l,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const A=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 4","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VIII/Lectura_Catedra_Evaluacion_4.md","filePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VIII/Lectura_Catedra_Evaluacion_4.md"}'),m={name:"materias/Proyecto_Sociotecnologico_III/documentacion/III-VIII/Lectura_Catedra_Evaluacion_4.md"};function p(g,e,I,h,v,b){const t=n("Mermaid");return o(),d("div",null,[e[1]||(e[1]=a('<h1 id="manual-de-estudio-profundo-evaluacion-4" tabindex="-1">Manual de Estudio Profundo: Evaluación 4 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-4" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 4&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-viii" tabindex="-1">Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VIII) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-viii" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VIII)&quot;">​</a></h2><h3 id="eje-tematico-construccion-del-prototipo-funcional-avanzado-gitflow-y-2do-avance" tabindex="-1">Eje Temático: Construcción del Prototipo Funcional Avanzado, GitFlow y 2do Avance <a class="header-anchor" href="#eje-tematico-construccion-del-prototipo-funcional-avanzado-gitflow-y-2do-avance" aria-label="Permalink to &quot;Eje Temático: Construcción del Prototipo Funcional Avanzado, GitFlow y 2do Avance&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-demostracion-de-madurez-tecnica" tabindex="-1">🧭 Introducción: La Demostración de Madurez Técnica <a class="header-anchor" href="#🧭-introduccion-la-demostracion-de-madurez-tecnica" aria-label="Permalink to &quot;🧭 Introducción: La Demostración de Madurez Técnica&quot;">​</a></h2><p>El cierre del Trimestre VIII exige la materialización física del sistema: <strong>el prototipo funcional avanzado</strong>. En este hito, el software debe demostrar no solo que almacena y consulta datos, sino que opera con estabilidad bajo estándares de seguridad web, gestión de roles de usuario y control estricto de concurrencia.</p><p>Asimismo, se evalúa la disciplina de ingeniería del equipo mediante el análisis de su historial de ramas y confirmaciones en el repositorio Git institucional.</p><hr><h2 id="🐙-capitulo-i-flujo-de-trabajo-profesional-con-gitflow" tabindex="-1">🐙 CAPÍTULO I: Flujo de Trabajo Profesional con GitFlow <a class="header-anchor" href="#🐙-capitulo-i-flujo-de-trabajo-profesional-con-gitflow" aria-label="Permalink to &quot;🐙 CAPÍTULO I: Flujo de Trabajo Profesional con GitFlow&quot;">​</a></h2><p>En el Trayecto III, los equipos deben abandonar el trabajo directo en la rama principal, adoptando el estándar de la industria <strong>GitFlow</strong>:</p>',10)),(o(),s(u,null,{default:i(()=>[l(t,{id:"mermaid-26",class:"mermaid",graph:"gitGraph%0A%20%20%20%20commit%20id%3A%20%22v0.1-init%22%0A%20%20%20%20branch%20develop%0A%20%20%20%20checkout%20develop%0A%20%20%20%20commit%20id%3A%20%22config-bd-mvc%22%0A%20%20%20%20branch%20feature%2Fauth-rbac%0A%20%20%20%20checkout%20feature%2Fauth-rbac%0A%20%20%20%20commit%20id%3A%20%22login-jwt-bcrypt%22%0A%20%20%20%20commit%20id%3A%20%22middleware-roles%22%0A%20%20%20%20checkout%20develop%0A%20%20%20%20merge%20feature%2Fauth-rbac%20id%3A%20%22merge-auth%22%0A%20%20%20%20branch%20feature%2Freportes-pdf%0A%20%20%20%20checkout%20feature%2Freportes-pdf%0A%20%20%20%20commit%20id%3A%20%22generador-pdf-qr%22%0A%20%20%20%20checkout%20develop%0A%20%20%20%20merge%20feature%2Freportes-pdf%20id%3A%20%22merge-reportes%22%0A%20%20%20%20branch%20release%2Fv0.8%0A%20%20%20%20checkout%20release%2Fv0.8%0A%20%20%20%20commit%20id%3A%20%22correccion-estilos%22%0A%20%20%20%20checkout%20main%0A%20%20%20%20merge%20release%2Fv0.8%20id%3A%20%22v0.8-prototipo-eval%22%0A%20%20%20%20checkout%20develop%0A%20%20%20%20merge%20release%2Fv0.8%20id%3A%20%22sync-develop%22%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="_1-1-reglas-de-oro-en-gitflow-para-pst-iii" tabindex="-1">1.1 Reglas de Oro en GitFlow para PST III <a class="header-anchor" href="#_1-1-reglas-de-oro-en-gitflow-para-pst-iii" aria-label="Permalink to &quot;1.1 Reglas de Oro en GitFlow para PST III&quot;">​</a></h3><ol><li><strong>La rama <code>main</code> es sagrada:</strong> Solo contiene versiones estables y aprobadas que ya fueron presentadas ante el tutor o la comunidad.</li><li><strong>Desarrollo en <code>develop</code>:</strong> Todo el trabajo diario se consolida en la rama <code>develop</code>.</li><li><strong>Revisión de Código (<em>Pull Requests / Merge Requests</em>):</strong> Ningún estudiante fusiona su código en <code>develop</code> sin que al menos otro compañero de equipo haya revisado los cambios para evitar que errores tontos rompan el sistema.</li></ol><hr><h2 id="🛡️-capitulo-ii-medidas-obligatorias-de-seguridad-web-en-pst-iii" tabindex="-1">🛡️ CAPÍTULO II: Medidas Obligatorias de Seguridad Web en PST III <a class="header-anchor" href="#🛡️-capitulo-ii-medidas-obligatorias-de-seguridad-web-en-pst-iii" aria-label="Permalink to &quot;🛡️ CAPÍTULO II: Medidas Obligatorias de Seguridad Web en PST III&quot;">​</a></h2><p>El prototipo funcional debe proteger la información comunitaria contra las vulnerabilidades más comunes del <strong>OWASP Top 10</strong>:</p><table tabindex="0"><thead><tr><th>Vulnerabilidad</th><th>Riesgo en el Proyecto</th><th>Mecanismo de Defensa Implementado</th></tr></thead><tbody><tr><td><strong>SQL Injection (SQLi)</strong></td><td>Robo o destrucción de la base de datos completa.</td><td>Uso estricto de <strong>Sentencias Preparadas con PDO / ORM</strong>. Jamás concatenar texto del usuario.</td></tr><tr><td><strong>Cross-Site Scripting (XSS)</strong></td><td>Inyección de código JavaScript malicioso en nombres o comentarios.</td><td><strong>Sanitización y Escapado de Entradas</strong> (<code>htmlspecialchars()</code> o plantillas seguras automáticas como Blade/Twig).</td></tr><tr><td><strong>Cross-Site Request Forgery (CSRF)</strong></td><td>Ejecución de transacciones forzadas sin conocimiento del usuario autenticado.</td><td>Implementación de <strong>Tokens CSRF únicos por formulario</strong> validados en el servidor.</td></tr><tr><td><strong>Robo de Sesión / Fuerza Bruta</strong></td><td>Adivinación de contraseñas de usuarios administradores.</td><td><strong>Límite de intentos fallidos</strong> (bloqueo por 15 min tras 5 intentos) y cookies seguras (<code>HttpOnly</code>, <code>SameSite=Lax</code>).</td></tr></tbody></table><hr><h2 id="📋-capitulo-iii-el-2do-informe-de-avance-afinar-y-la-demostracion" tabindex="-1">📋 CAPÍTULO III: El 2do Informe de Avance (Afinar) y la Demostración <a class="header-anchor" href="#📋-capitulo-iii-el-2do-informe-de-avance-afinar-y-la-demostracion" aria-label="Permalink to &quot;📋 CAPÍTULO III: El 2do Informe de Avance (Afinar) y la Demostración&quot;">​</a></h2><p>La Evaluación 4 del Trimestre VIII evalúa dos productos indisolubles:</p><h3 id="_3-1-contenido-del-2do-informe-de-avance" tabindex="-1">3.1 Contenido del 2do Informe de Avance <a class="header-anchor" href="#_3-1-contenido-del-2do-informe-de-avance" aria-label="Permalink to &quot;3.1 Contenido del 2do Informe de Avance&quot;">​</a></h3><ul><li><strong>Capítulo II (Marco Metodológico Consolidado):</strong> Justificación de la metodología, descripción de fases/sprints ejecutados y cuadro comparativo de herramientas libres.</li><li><strong>Capítulo III (Propuesta Técnica y Modelado Avanzado):</strong> Diagramas UML (casos de uso, secuencia, clases, paquetes, despliegue), diseño de base de datos relacional y diccionario de datos.</li><li><strong>Evidencias de Trabajo de Campo:</strong> Bitácoras de visitas a la comunidad con firmas y sellos institucionales.</li></ul><h3 id="_3-2-protocolo-de-la-demostracion-en-vivo" tabindex="-1">3.2 Protocolo de la Demostración en Vivo <a class="header-anchor" href="#_3-2-protocolo-de-la-demostracion-en-vivo" aria-label="Permalink to &quot;3.2 Protocolo de la Demostración en Vivo&quot;">​</a></h3><ol><li><strong>Puesta a Cero:</strong> Demostración con base de datos limpia o con datos sembrados de prueba reales.</li><li><strong>Flujo de Roles:</strong> Iniciar sesión como <code>Administrador</code>, crear un nuevo <code>Operador</code> con permisos restringidos, cerrar sesión e ingresar con el nuevo operador para evidenciar que no puede acceder a las funciones críticas de configuración.</li><li><strong>Transacción Completa:</strong> Ejecutar un trámite completo, validar que se descuenten los insumos o se registre la solicitud, y emitir el reporte en PDF con membrete institucional.</li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-4" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 4 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-4" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 4&quot;">​</a></h2><p>Para aprobar la Evaluación 4 y cerrar el Trimestre VIII:</p><ol><li><strong>2do Informe de Avance Encuadernado y Digital:</strong> Con todos los capítulos metodológico y técnico aprobados.</li><li><strong>Prototipo Funcional Operativo:</strong> Demostrado en vivo ante el jurado evaluador institucional.</li><li><strong>Repositorio Git Activo:</strong> Con ramas de trabajo claras, commits semánticos y evidencia de trabajo colaborativo equitativo.</li></ol>',17))])}const _=r(m,[["render",p]]);export{A as __pageData,_ as default};
